=== FILE: axil_timer.v ===
`default_nettype none

// axil_timer: 32-bit down-counting timer, one-shot and periodic modes,
// level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] REG_CTRL   = 2'd0;
    localparam [1:0] REG_LOAD   = 2'd1;
    localparam [1:0] REG_COUNT  = 2'd2;
    localparam [1:0] REG_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // Write channel holding state
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg [ADDR_WIDTH-1:0] awaddr_q;
    reg [31:0]           wdata_q;
    reg [3:0]            wstrb_q;

    // ------------------------------------------------------------------
    // Timer state and its next-state values
    // ------------------------------------------------------------------
    reg        en;
    reg        ie;
    reg        mode;
    reg        expired;
    reg [31:0] load;
    reg [31:0] count;

    reg        en_d;
    reg        ie_d;
    reg        mode_d;
    reg        expired_d;
    reg [31:0] load_d;
    reg [31:0] count_d;

    // ------------------------------------------------------------------
    // Handshakes
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    // Both halves of a write present (held or arriving) on this edge.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? awaddr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? wdata_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? wstrb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: word aligned and below 0x10
    // ------------------------------------------------------------------
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != REG_COUNT);

    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == REG_CTRL) && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == REG_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == REG_STATUS) &&
                    wr_strb[0] && wr_data[0];

    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    // Last cycle of a count: EN set and COUNT at 1 or 0.
    wire count_end = en && (count <= 32'd1);

    // ------------------------------------------------------------------
    // Read data mux
    // ------------------------------------------------------------------
    reg [31:0] rd_value;
    always @* begin
        rd_value = 32'd0;
        case (rd_idx)
            REG_CTRL:   rd_value = {29'd0, mode, ie, en};
            REG_LOAD:   rd_value = load;
            REG_COUNT:  rd_value = count;
            REG_STATUS: rd_value = {31'd0, expired};
            default:    rd_value = 32'd0;
        endcase
        if (!rd_mapped) begin
            rd_value = 32'd0;
        end
    end

    // ------------------------------------------------------------------
    // Timer next state; later assignments take priority
    // ------------------------------------------------------------------
    always @* begin
        en_d      = en;
        ie_d      = ie;
        mode_d    = mode;
        expired_d = expired;
        load_d    = load;
        count_d   = count;

        // 1. Count step
        if (en) begin
            if (count_end) begin
                if (mode) begin
                    count_d = load;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count - 32'd1;
            end
        end

        // 2. Expiry: clear first, then a count end wins
        if (wr_clear) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write wins for EN and COUNT
        if (wr_ctrl) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            en_d   = wr_data[0];
            if (wr_data[0]) begin
                count_d = load;
            end
        end

        // 4. LOAD write, byte merge
        if (wr_load) begin
            if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
            if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
            if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
            if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
        end
    end

    // ------------------------------------------------------------------
    // Timer registers
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            en      <= en_d;
            ie      <= ie_d;
            mode    <= mode_d;
            expired <= expired_d;
            load    <= load_d;
            count   <= count_d;
        end
    end

    // ------------------------------------------------------------------
    // Write channel registers
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            awaddr_q      <= {ADDR_WIDTH{1'b0}};
            wdata_q       <= 32'd0;
            wstrb_q       <= 4'd0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
        end else begin
            if (do_write) begin
                aw_held <= 1'b0;
                w_held  <= 1'b0;
            end else begin
                if (aw_hs) begin
                    aw_held  <= 1'b1;
                    awaddr_q <= s_axil_awaddr;
                end
                if (w_hs) begin
                    w_held  <= 1'b1;
                    wdata_q <= s_axil_wdata;
                    wstrb_q <= s_axil_wstrb;
                end
            end

            if (do_write) begin
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_bready) begin
                s_axil_bvalid <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel registers
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else begin
            if (ar_hs) begin
                s_axil_rvalid <= 1'b1;
                s_axil_rdata  <= rd_value;
                s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            end else if (s_axil_rready) begin
                s_axil_rvalid <= 1'b0;
            end
        end
    end

    assign irq = expired && ie;

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// Self-checking testbench for axil_timer.
// Top: axil_timer_tb. It runs two lanes (ADDR_WIDTH 4 and 8) and prints one verdict.

module axil_timer_tb;
    reg [8*64-1:0] nonce;
    wire           done4;
    wire           done8;
    wire [31:0]    pass4;
    wire [31:0]    fail4;
    wire [31:0]    pass8;
    wire [31:0]    fail8;
    integer        passed;
    integer        failed;
    integer        waited;

    axil_timer_tb_lane #(.ADDR_WIDTH(4)) lane4 (
        .done(done4), .n_pass(pass4), .n_fail(fail4)
    );
    axil_timer_tb_lane #(.ADDR_WIDTH(8)) lane8 (
        .done(done8), .n_pass(pass8), .n_fail(fail8)
    );

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        waited = 0;
        #1;
        while ((done4 !== 1'b1 || done8 !== 1'b1) && waited < 2000000) begin
            #10;
            waited = waited + 1;
        end
        passed = pass4 + pass8;
        failed = fail4 + fail8;
        if (done4 !== 1'b1 || done8 !== 1'b1) begin
            $error("timeout: test lanes did not finish");
            failed = failed + 1;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

module axil_timer_tb_lane #(
    parameter integer ADDR_WIDTH = 4
) (
    output reg         done,
    output wire [31:0] n_pass,
    output wire [31:0] n_fail
);
    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg                  aresetn = 1'b0;
    reg [ADDR_WIDTH-1:0] awaddr  = {ADDR_WIDTH{1'b0}};
    reg                  awvalid = 1'b0;
    reg [31:0]           wdata   = 32'd0;
    reg [3:0]            wstrb   = 4'd0;
    reg                  wvalid  = 1'b0;
    reg                  bready  = 1'b0;
    reg [ADDR_WIDTH-1:0] araddr  = {ADDR_WIDTH{1'b0}};
    reg                  arvalid = 1'b0;
    reg                  rready  = 1'b0;

    wire        awready;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    wire        irq;

    axil_timer #(.ADDR_WIDTH(ADDR_WIDTH)) dut (
        .aclk(clk),
        .aresetn(aresetn),
        .s_axil_awaddr(awaddr),
        .s_axil_awvalid(awvalid),
        .s_axil_awready(awready),
        .s_axil_wdata(wdata),
        .s_axil_wstrb(wstrb),
        .s_axil_wvalid(wvalid),
        .s_axil_wready(wready),
        .s_axil_bresp(bresp),
        .s_axil_bvalid(bvalid),
        .s_axil_bready(bready),
        .s_axil_araddr(araddr),
        .s_axil_arvalid(arvalid),
        .s_axil_arready(arready),
        .s_axil_rdata(rdata),
        .s_axil_rresp(rresp),
        .s_axil_rvalid(rvalid),
        .s_axil_rready(rready),
        .irq(irq)
    );

    integer passed = 0;
    integer failed = 0;
    assign n_pass = passed;
    assign n_fail = failed;

    // Rising-edge counter: read at a negedge, it holds the number of edges so far.
    reg [31:0] cyc = 32'd0;
    always @(posedge clk) cyc <= cyc + 32'd1;

    // irq rise monitor: records the cycle count after the edge on which irq rose.
    reg        irq_q        = 1'b0;
    integer    irq_rises    = 0;
    reg [31:0] irq_rise_cyc = 32'd0;
    always @(negedge clk) begin
        if (irq && !irq_q) begin
            irq_rises    <= irq_rises + 1;
            irq_rise_cyc <= cyc;
        end
        irq_q <= irq;
    end

    reg [1:0]  r;
    reg [31:0] d;
    reg [31:0] e;
    reg [31:0] s;
    reg [31:0] t;
    reg [31:0] last_eff;
    integer    before;
    integer    p;

    // ---------------- check helpers ----------------
    task chk(input cond, input integer id);
    begin
        if (cond) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d failed at cycle %0d", ADDR_WIDTH, id, cyc);
        end
    end
    endtask

    task chk32(input [31:0] got, input [31:0] exp, input integer id);
    begin
        if (got === exp) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d: got 0x%08h, expected 0x%08h", ADDR_WIDTH, id, got, exp);
        end
    end
    endtask

    task chk2(input [1:0] got, input [1:0] exp, input integer id);
    begin
        if (got === exp) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d: resp %b, expected %b", ADDR_WIDTH, id, got, exp);
        end
    end
    endtask

    task wait_cycles(input [31:0] n);
    begin
        repeat (n) @(negedge clk);
    end
    endtask

    task wait_rise(input integer prev, input [31:0] timeout, input integer id);
        reg [31:0] g;
    begin
        g = 32'd0;
        while (irq_rises <= prev && g < timeout) begin
            @(negedge clk);
            g = g + 32'd1;
        end
        chk(irq_rises > prev, id);
    end
    endtask

    // ---------------- bus tasks ----------------
    // order: 0 AW and W together, 1 AW first, 2 W first.
    // eff: the cycle count after the edge on which the write took effect.
    task axi_write(input [31:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay,
                   output [1:0] resp, output [31:0] eff);
        reg     aw_done;
        reg     w_done;
        reg     aw_fire;
        reg     w_fire;
        reg [1:0] resp0;
        integer guard;
        integer k;
    begin
        aw_done = 1'b0;
        w_done  = 1'b0;
        guard   = 0;
        @(negedge clk);
        if (order != 2) begin
            awaddr  = addr[ADDR_WIDTH-1:0];
            awvalid = 1'b1;
        end
        if (order != 1) begin
            wdata  = data;
            wstrb  = strb;
            wvalid = 1'b1;
        end
        while (!(aw_done && w_done) && guard < 50) begin
            aw_fire = awvalid && awready;
            w_fire  = wvalid && wready;
            @(negedge clk);
            guard = guard + 1;
            if (aw_fire) begin
                aw_done = 1'b1;
                awvalid = 1'b0;
            end
            if (w_fire) begin
                w_done = 1'b1;
                wvalid = 1'b0;
            end
            if (aw_done && !w_done) begin
                chk(awready === 1'b0, 106);
                if (!wvalid) begin
                    wdata  = data;
                    wstrb  = strb;
                    wvalid = 1'b1;
                end
            end
            if (w_done && !aw_done) begin
                chk(wready === 1'b0, 107);
                if (!awvalid) begin
                    awaddr  = addr[ADDR_WIDTH-1:0];
                    awvalid = 1'b1;
                end
            end
        end
        eff = cyc;
        chk(aw_done && w_done, 100);
        chk(bvalid === 1'b1, 101);
        resp0 = bresp;
        chk(awready === 1'b0 && wready === 1'b0, 102);
        for (k = 0; k < bdelay; k = k + 1) begin
            @(negedge clk);
            chk(bvalid === 1'b1 && bresp === resp0, 103);
            chk(awready === 1'b0 && wready === 1'b0, 105);
        end
        bready = 1'b1;
        @(negedge clk);
        bready = 1'b0;
        chk(bvalid === 1'b0, 104);
        resp = resp0;
    end
    endtask

    task axi_read(input [31:0] addr, input integer rdelay,
                  output [31:0] data, output [1:0] resp);
        integer guard;
        integer k;
    begin
        guard = 0;
        @(negedge clk);
        araddr  = addr[ADDR_WIDTH-1:0];
        arvalid = 1'b1;
        while (arready !== 1'b1 && guard < 50) begin
            @(negedge clk);
            guard = guard + 1;
        end
        @(negedge clk);
        arvalid = 1'b0;
        chk(rvalid === 1'b1, 110);
        chk(arready === 1'b0, 111);
        data = rdata;
        resp = rresp;
        for (k = 0; k < rdelay; k = k + 1) begin
            @(negedge clk);
            chk(rvalid === 1'b1 && rdata === data && rresp === resp && arready === 1'b0, 112);
        end
        rready = 1'b1;
        @(negedge clk);
        rready = 1'b0;
        chk(rvalid === 1'b0, 113);
    end
    endtask

    task wr_expect(input [31:0] addr, input [31:0] data, input [3:0] strb,
                   input [1:0] exp_resp, input integer id);
        reg [1:0]  got;
        reg [31:0] eff;
    begin
        axi_write(addr, data, strb, 0, 0, got, eff);
        last_eff = eff;
        chk2(got, exp_resp, id);
    end
    endtask

    task rd_expect(input [31:0] addr, input [31:0] exp_data, input [1:0] exp_resp,
                   input integer id);
        reg [31:0] got_d;
        reg [1:0]  got_r;
    begin
        axi_read(addr, 0, got_d, got_r);
        chk32(got_d, exp_data, id);
        chk2(got_r, exp_resp, id);
    end
    endtask

    // One-shot count with IE set, timed to the cycle; a LOAD of 0 counts as 1.
    task oneshot_test(input [31:0] n, input [31:0] len, input integer id);
        reg [31:0] start;
        integer    prev;
    begin
        wr_expect(32'h4, n, 4'hF, OKAY, id);
        prev = irq_rises;
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, id + 1);
        start = last_eff;
        wait_rise(prev, len + 32'd20, id + 2);
        chk32(irq_rise_cyc - start, len, id + 3);
        rd_expect(32'h0, 32'h0000_0002, OKAY, id + 4);
        rd_expect(32'h8, 32'h0, OKAY, id + 5);
        rd_expect(32'hC, 32'h1, OKAY, id + 6);
        chk(irq === 1'b1, id + 7);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, id + 8);
        chk(irq === 1'b0, id + 9);
        rd_expect(32'hC, 32'h0, OKAY, id + 10);
        wait_cycles(len * 32'd3 + 32'd10);
        chk(irq_rises == prev + 1, id + 11);
        chk(irq === 1'b0, id + 12);
    end
    endtask

    // ---------------- directed sequence ----------------
    initial begin
        done = 1'b0;
        aresetn = 1'b0;
        repeat (3) @(negedge clk);
        aresetn = 1'b1;
        @(negedge clk);

        // T1: reset values
        chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 1);
        chk(bvalid === 1'b0 && rvalid === 1'b0, 2);
        chk(irq === 1'b0, 3);
        rd_expect(32'h0, 32'h0, OKAY, 4);
        rd_expect(32'h4, 32'h0, OKAY, 5);
        rd_expect(32'h8, 32'h0, OKAY, 6);
        rd_expect(32'hC, 32'h0, OKAY, 7);

        // T2: LOAD with partial strobes
        wr_expect(32'h4, 32'hFFFF_FFFF, 4'hF, OKAY, 10);
        rd_expect(32'h4, 32'hFFFF_FFFF, OKAY, 11);
