// Self-checking testbench for axil_timer.
// Top: axil_timer_tb. It runs two lanes (ADDR_WIDTH 4 and 8) and prints one verdict.
// No identifier in this file is a SystemVerilog keyword.

module axil_timer_tb;
    reg [8*64-1:0] nonce;
    wire           done4;
    wire           done8;
    wire [31:0]    pass4;
    wire [31:0]    fail4;
    wire [31:0]    pass8;
    wire [31:0]    fail8;
    integer        passed;
    integer        failed;
    integer        waited;

    axil_timer_tb_lane #(.ADDR_WIDTH(4)) lane4 (
        .done(done4), .n_pass(pass4), .n_fail(fail4)
    );
    axil_timer_tb_lane #(.ADDR_WIDTH(8)) lane8 (
        .done(done8), .n_pass(pass8), .n_fail(fail8)
    );

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        waited = 0;
        #1;
        while ((done4 !== 1'b1 || done8 !== 1'b1) && waited < 2000000) begin
            #10;
            waited = waited + 1;
        end
        passed = pass4 + pass8;
        failed = fail4 + fail8;
        if (done4 !== 1'b1 || done8 !== 1'b1) begin
            $error("timeout: test lanes did not finish");
            failed = failed + 1;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

module axil_timer_tb_lane #(
    parameter integer ADDR_WIDTH = 4
) (
    output reg         done,
    output wire [31:0] n_pass,
    output wire [31:0] n_fail
);
    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg                  aresetn = 1'b0;
    reg [ADDR_WIDTH-1:0] awaddr  = {ADDR_WIDTH{1'b0}};
    reg                  awvalid = 1'b0;
    reg [31:0]           wdata   = 32'd0;
    reg [3:0]            wstrb   = 4'd0;
    reg                  wvalid  = 1'b0;
    reg                  bready  = 1'b0;
    reg [ADDR_WIDTH-1:0] araddr  = {ADDR_WIDTH{1'b0}};
    reg                  arvalid = 1'b0;
    reg                  rready  = 1'b0;

    wire        awready;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    wire        irq;

    axil_timer #(.ADDR_WIDTH(ADDR_WIDTH)) dut (
        .aclk(clk),
        .aresetn(aresetn),
        .s_axil_awaddr(awaddr),
        .s_axil_awvalid(awvalid),
        .s_axil_awready(awready),
        .s_axil_wdata(wdata),
        .s_axil_wstrb(wstrb),
        .s_axil_wvalid(wvalid),
        .s_axil_wready(wready),
        .s_axil_bresp(bresp),
        .s_axil_bvalid(bvalid),
        .s_axil_bready(bready),
        .s_axil_araddr(araddr),
        .s_axil_arvalid(arvalid),
        .s_axil_arready(arready),
        .s_axil_rdata(rdata),
        .s_axil_rresp(rresp),
        .s_axil_rvalid(rvalid),
        .s_axil_rready(rready),
        .irq(irq)
    );

    integer passed = 0;
    integer failed = 0;
    assign n_pass = passed;
    assign n_fail = failed;

    // Rising-edge counter: read at a negedge, it holds the number of edges so far.
    reg [31:0] cyc = 32'd0;
    always @(posedge clk) cyc <= cyc + 32'd1;

    // irq rise monitor: records the cycle count after the edge on which irq rose.
    reg        irq_q        = 1'b0;
    integer    irq_rises    = 0;
    reg [31:0] irq_rise_cyc = 32'd0;
    always @(negedge clk) begin
        if (irq && !irq_q) begin
            irq_rises    <= irq_rises + 1;
            irq_rise_cyc <= cyc;
        end
        irq_q <= irq;
    end

    reg [1:0]  r;
    reg [31:0] d;
    reg [31:0] e;
    reg [31:0] s;
    reg [31:0] t;
    reg [31:0] last_eff;
    integer    rises0;
    integer    p;

    // ---------------- check helpers ----------------
    task chk(input cond, input integer id);
    begin
        if (cond) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d failed at cycle %0d", ADDR_WIDTH, id, cyc);
        end
    end
    endtask

    task chk32(input [31:0] got, input [31:0] exp, input integer id);
    begin
        if (got === exp) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d: got 0x%08h, expected 0x%08h", ADDR_WIDTH, id, got, exp);
        end
    end
    endtask

    task chk2(input [1:0] got, input [1:0] exp, input integer id);
    begin
        if (got === exp) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("AW=%0d check %0d: resp %b, expected %b", ADDR_WIDTH, id, got, exp);
        end
    end
    endtask

    task wait_cycles(input [31:0] n);
    begin
        repeat (n) @(negedge clk);
    end
    endtask

    task wait_rise(input integer prev, input [31:0] timeout, input integer id);
        reg [31:0] g;
    begin
        g = 32'd0;
        while (irq_rises <= prev && g < timeout) begin
            @(negedge clk);
            g = g + 32'd1;
        end
        chk(irq_rises > prev, id);
    end
    endtask

    // ---------------- bus tasks ----------------
    // order: 0 AW and W together, 1 AW first, 2 W first.
    // eff: the cycle count after the edge on which the write took effect.
    task axi_write(input [31:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay,
                   output [1:0] resp, output [31:0] eff);
        reg     aw_done;
        reg     w_done;
        reg     aw_fire;
        reg     w_fire;
        reg [1:0] resp0;
        integer guard;
        integer k;
    begin
        aw_done = 1'b0;
        w_done  = 1'b0;
        guard   = 0;
        @(negedge clk);
        if (order != 2) begin
            awaddr  = addr[ADDR_WIDTH-1:0];
            awvalid = 1'b1;
        end
        if (order != 1) begin
            wdata  = data;
            wstrb  = strb;
            wvalid = 1'b1;
        end
        while (!(aw_done && w_done) && guard < 50) begin
            aw_fire = awvalid && awready;
            w_fire  = wvalid && wready;
            @(negedge clk);
            guard = guard + 1;
            if (aw_fire) begin
                aw_done = 1'b1;
                awvalid = 1'b0;
            end
            if (w_fire) begin
                w_done = 1'b1;
                wvalid = 1'b0;
            end
            if (aw_done && !w_done) begin
                chk(awready === 1'b0, 106);
                if (!wvalid) begin
                    wdata  = data;
                    wstrb  = strb;
                    wvalid = 1'b1;
                end
            end
            if (w_done && !aw_done) begin
                chk(wready === 1'b0, 107);
                if (!awvalid) begin
                    awaddr  = addr[ADDR_WIDTH-1:0];
                    awvalid = 1'b1;
                end
            end
        end
        eff = cyc;
        chk(aw_done && w_done, 100);
        chk(bvalid === 1'b1, 101);
        resp0 = bresp;
        chk(awready === 1'b0 && wready === 1'b0, 102);
        for (k = 0; k < bdelay; k = k + 1) begin
            @(negedge clk);
            chk(bvalid === 1'b1 && bresp === resp0, 103);
            chk(awready === 1'b0 && wready === 1'b0, 105);
        end
        bready = 1'b1;
        @(negedge clk);
        bready = 1'b0;
        chk(bvalid === 1'b0, 104);
        resp = resp0;
    end
    endtask

    task axi_read(input [31:0] addr, input integer rdelay,
                  output [31:0] data, output [1:0] resp);
        integer guard;
        integer k;
    begin
        guard = 0;
        @(negedge clk);
        araddr  = addr[ADDR_WIDTH-1:0];
        arvalid = 1'b1;
        while (arready !== 1'b1 && guard < 50) begin
            @(negedge clk);
            guard = guard + 1;
        end
        @(negedge clk);
        arvalid = 1'b0;
        chk(rvalid === 1'b1, 110);
        chk(arready === 1'b0, 111);
        data = rdata;
        resp = rresp;
        for (k = 0; k < rdelay; k = k + 1) begin
            @(negedge clk);
            chk(rvalid === 1'b1 && rdata === data && rresp === resp && arready === 1'b0, 112);
        end
        rready = 1'b1;
        @(negedge clk);
        rready = 1'b0;
        chk(rvalid === 1'b0, 113);
    end
    endtask

    task wr_expect(input [31:0] addr, input [31:0] data, input [3:0] strb,
                   input [1:0] exp_resp, input integer id);
        reg [1:0]  got;
        reg [31:0] eff;
    begin
        axi_write(addr, data, strb, 0, 0, got, eff);
        last_eff = eff;
        chk2(got, exp_resp, id);
    end
    endtask

    task rd_expect(input [31:0] addr, input [31:0] exp_data, input [1:0] exp_resp,
                   input integer id);
        reg [31:0] got_d;
        reg [1:0]  got_r;
    begin
        axi_read(addr, 0, got_d, got_r);
        chk32(got_d, exp_data, id);
        chk2(got_r, exp_resp, id);
    end
    endtask

    // One-shot count with IE set, timed to the cycle; a LOAD of 0 counts as 1.
    task oneshot_test(input [31:0] n, input [31:0] len, input integer id);
        reg [31:0] start;
        integer    prev;
    begin
        wr_expect(32'h4, n, 4'hF, OKAY, id);
        prev = irq_rises;
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, id + 1);
        start = last_eff;
        wait_rise(prev, len + 32'd20, id + 2);
        chk32(irq_rise_cyc - start, len, id + 3);
        rd_expect(32'h0, 32'h0000_0002, OKAY, id + 4);
        rd_expect(32'h8, 32'h0, OKAY, id + 5);
        rd_expect(32'hC, 32'h1, OKAY, id + 6);
        chk(irq === 1'b1, id + 7);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, id + 8);
        chk(irq === 1'b0, id + 9);
        rd_expect(32'hC, 32'h0, OKAY, id + 10);
        wait_cycles(len * 32'd3 + 32'd10);
        chk(irq_rises == prev + 1, id + 11);
        chk(irq === 1'b0, id + 12);
    end
    endtask

    // ---------------- directed sequence ----------------
    initial begin
        done = 1'b0;
        aresetn = 1'b0;
        repeat (3) @(negedge clk);
        aresetn = 1'b1;
        @(negedge clk);

        // T1: reset values
        chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 1);
        chk(bvalid === 1'b0 && rvalid === 1'b0, 2);
        chk(irq === 1'b0, 3);
        rd_expect(32'h0, 32'h0, OKAY, 4);
        rd_expect(32'h4, 32'h0, OKAY, 5);
        rd_expect(32'h8, 32'h0, OKAY, 6);
        rd_expect(32'hC, 32'h0, OKAY, 7);

        // T2: LOAD with partial strobes
        wr_expect(32'h4, 32'hFFFF_FFFF, 4'hF, OKAY, 10);
        rd_expect(32'h4, 32'hFFFF_FFFF, OKAY, 11);
        wr_expect(32'h4, 32'h1234_5678, 4'b0101, OKAY, 12);
        rd_expect(32'h4, 32'hFF34_FF78, OKAY, 13);
        wr_expect(32'h4, 32'hAABB_CCDD, 4'b1010, OKAY, 14);
        rd_expect(32'h4, 32'hAA34_CC78, OKAY, 15);
        wr_expect(32'h4, 32'h0000_0000, 4'b0000, OKAY, 16);
        rd_expect(32'h4, 32'hAA34_CC78, OKAY, 17);

        // T3: both channel orders and response backpressure
        axi_write(32'h4, 32'h0000_1111, 4'hF, 1, 4, r, e);
        chk2(r, OKAY, 20);
        axi_read(32'h4, 3, d, r);
        chk32(d, 32'h0000_1111, 21);
        chk2(r, OKAY, 22);
        axi_write(32'h4, 32'h0000_2222, 4'hF, 2, 6, r, e);
        chk2(r, OKAY, 23);
        axi_read(32'h4, 0, d, r);
        chk32(d, 32'h0000_2222, 24);
        chk2(r, OKAY, 25);
        axi_write(32'h4, 32'h0000_3333, 4'hF, 0, 2, r, e);
        chk2(r, OKAY, 26);
        axi_read(32'h4, 5, d, r);
        chk32(d, 32'h0000_3333, 27);
        chk2(r, OKAY, 28);

        // T4: COUNT read only, SLVERR policy, no aliasing
        wr_expect(32'h8, 32'h0000_00FF, 4'hF, SLVERR, 30);
        rd_expect(32'h8, 32'h0, OKAY, 31);
        rd_expect(32'h4, 32'h0000_3333, OKAY, 32);
        wr_expect(32'h1, 32'hFFFF_FFFF, 4'hF, SLVERR, 33);
        wr_expect(32'h6, 32'h5555_5555, 4'hF, SLVERR, 34);
        wr_expect(32'hF, 32'h0000_0001, 4'hF, SLVERR, 35);
        rd_expect(32'h0, 32'h0, OKAY, 36);
        rd_expect(32'h4, 32'h0000_3333, OKAY, 37);
        rd_expect(32'h1, 32'h0, SLVERR, 38);
        rd_expect(32'h5, 32'h0, SLVERR, 39);
        rd_expect(32'h2, 32'h0, SLVERR, 40);
        rd_expect(32'h7, 32'h0, SLVERR, 41);
        if (ADDR_WIDTH > 4) begin
            wr_expect(32'h10, 32'h0000_0007, 4'hF, SLVERR, 42);
            wr_expect(32'h14, 32'hDEAD_BEEF, 4'hF, SLVERR, 43);
            wr_expect(32'hF4, 32'h0000_1234, 4'hF, SLVERR, 44);
            rd_expect(32'h0, 32'h0, OKAY, 45);
            rd_expect(32'h4, 32'h0000_3333, OKAY, 46);
            rd_expect(32'h14, 32'h0, SLVERR, 47);
            rd_expect(32'h10, 32'h0, SLVERR, 48);
            rd_expect(32'h40, 32'h0, SLVERR, 49);
            rd_expect(32'hFC, 32'h0, SLVERR, 50);
            chk(irq === 1'b0, 51);
            rd_expect(32'h8, 32'h0, OKAY, 52);
        end

        // T5: CTRL write without wstrb[0] changes nothing
        wr_expect(32'h0, 32'h0000_0007, 4'b1110, OKAY, 55);
        rd_expect(32'h0, 32'h0, OKAY, 56);
        rd_expect(32'h8, 32'h0, OKAY, 57);
        chk(irq === 1'b0, 58);

        // T6: one-shot counts timed to the cycle
        oneshot_test(32'd1,   32'd1,   60);
        oneshot_test(32'd2,   32'd2,   80);
        oneshot_test(32'd7,   32'd7,   100);
        oneshot_test(32'd0,   32'd1,   120);
        oneshot_test(32'd100, 32'd100, 140);

        // T7: interrupt enable on a pending expiry; STATUS clear rules
        wr_expect(32'h4, 32'd5, 4'hF, OKAY, 200);
        wr_expect(32'h0, 32'h0000_0001, 4'hF, OKAY, 201);
        wait_cycles(20);
        chk(irq === 1'b0, 202);
        rd_expect(32'hC, 32'h1, OKAY, 203);
        rd_expect(32'h0, 32'h0, OKAY, 204);
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0002, 4'hF, OKAY, 205);
        e = last_eff;
        chk(irq === 1'b1, 206);
        wait_cycles(1);
        chk(irq_rises == rises0 + 1, 207);
        chk32(irq_rise_cyc, e, 208);
        wr_expect(32'h0, 32'h0000_0000, 4'hF, OKAY, 209);
        chk(irq === 1'b0, 210);
        rd_expect(32'hC, 32'h1, OKAY, 211);
        wr_expect(32'hC, 32'h0, 4'hF, OKAY, 212);
        rd_expect(32'hC, 32'h1, OKAY, 213);
        wr_expect(32'hC, 32'h1, 4'hE, OKAY, 214);
        rd_expect(32'hC, 32'h1, OKAY, 215);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 216);
        rd_expect(32'hC, 32'h0, OKAY, 217);

        // T8: periodic counts timed over several periods
        wr_expect(32'h4, 32'd12, 4'hF, OKAY, 300);
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0007, 4'hF, OKAY, 301);
        s = last_eff;
        for (p = 1; p <= 4; p = p + 1) begin
            wait_rise(rises0, 32'd40, 302);
            chk32(irq_rise_cyc - s, 32'd12 * p, 303);
            rises0 = irq_rises;
            wr_expect(32'hC, 32'h1, 4'h1, OKAY, 304);
            chk(irq === 1'b0, 305);
        end
        rd_expect(32'h0, 32'h0000_0007, OKAY, 306);
        axi_read(32'h8, 0, d, r);
        chk(d >= 32'd1 && d <= 32'd12, 307);
        chk2(r, OKAY, 308);

        // T8b: a STATUS clear landing on a count end keeps EXPIRED
        wr_expect(32'h0, 32'h0, 4'hF, OKAY, 330);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 331);
        chk(irq === 1'b0, 332);
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0007, 4'hF, OKAY, 333);
        s = last_eff;
        wait_rise(rises0, 32'd40, 334);
        chk32(irq_rise_cyc - s, 32'd12, 335);
        rises0 = irq_rises;
        while (cyc != s + 32'd22) @(negedge clk);
        axi_write(32'hC, 32'h1, 4'h1, 0, 0, r, e);
        chk2(r, OKAY, 336);
        chk32(e, s + 32'd24, 337);
        chk(irq === 1'b1, 338);
        rd_expect(32'hC, 32'h1, OKAY, 339);
        chk(irq_rises == rises0, 340);
        wr_expect(32'h0, 32'h0, 4'hF, OKAY, 341);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 342);
        chk(irq === 1'b0, 343);

        // T9: a stop freezes COUNT
        wr_expect(32'h4, 32'd50, 4'hF, OKAY, 400);
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, 401);
        s = last_eff;
        wait_cycles(10);
        wr_expect(32'h0, 32'h0000_0002, 4'hF, OKAY, 402);
        t = last_eff;
        rd_expect(32'h8, 32'd50 - (t - s), OKAY, 403);
        wait_cycles(20);
        rd_expect(32'h8, 32'd50 - (t - s), OKAY, 404);
        rd_expect(32'h0, 32'h0000_0002, OKAY, 405);
        wait_cycles(60);
        chk(irq_rises == rises0, 406);
        chk(irq === 1'b0, 407);

        // T10: restart from stopped, then restart while running
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, 420);
        wait_cycles(15);
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, 421);
        t = last_eff;
        wait_rise(rises0, 32'd80, 422);
        chk32(irq_rise_cyc - t, 32'd50, 423);
        wait_cycles(5);
        chk(irq_rises == rises0 + 1, 424);
        rd_expect(32'h0, 32'h0000_0002, OKAY, 425);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 426);
        chk(irq === 1'b0, 427);

        // T11: a CTRL start landing on a count end wins for EN and COUNT
        wr_expect(32'h4, 32'd10, 4'hF, OKAY, 440);
        rises0 = irq_rises;
        wr_expect(32'h0, 32'h0000_0003, 4'hF, OKAY, 441);
        s = last_eff;
        while (cyc != s + 32'd8) @(negedge clk);
        axi_write(32'h0, 32'h0000_0003, 4'hF, 0, 0, r, e);
        chk2(r, OKAY, 442);
        chk32(e, s + 32'd10, 443);
        wait_cycles(1);
        chk(irq_rises == rises0 + 1, 444);
        chk32(irq_rise_cyc, s + 32'd10, 445);
        rd_expect(32'h0, 32'h0000_0003, OKAY, 446);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 447);
        chk(irq === 1'b0, 448);
        wait_rise(rises0 + 1, 32'd30, 449);
        chk32(irq_rise_cyc - e, 32'd10, 450);
        rd_expect(32'h0, 32'h0000_0002, OKAY, 451);
        wr_expect(32'hC, 32'h1, 4'h1, OKAY, 452);
        chk(irq === 1'b0, 453);

        // T12: reset during a periodic count
        wr_expect(32'h4, 32'd30, 4'hF, OKAY, 500);
        wr_expect(32'h0, 32'h0000_0007, 4'hF, OKAY, 501);
        wait_cycles(10);
        aresetn = 1'b0;
        repeat (2) @(negedge clk);
        aresetn = 1'b1;
        @(negedge clk);
        chk(irq === 1'b0, 502);
        chk(bvalid === 1'b0 && rvalid === 1'b0, 503);
        chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 504);
        rd_expect(32'h0, 32'h0, OKAY, 505);
        rd_expect(32'h4, 32'h0, OKAY, 506);
        rd_expect(32'h8, 32'h0, OKAY, 507);
        rd_expect(32'hC, 32'h0, OKAY, 508);
        rises0 = irq_rises;
        wait_cycles(100);
        chk(irq_rises == rises0, 509);
        chk(irq === 1'b0, 510);
        rd_expect(32'h8, 32'h0, OKAY, 511);

        done = 1'b1;
    end
endmodule
